import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { PersonCells, PersonColumnHead } from '../../slots/defs/personRow';
import type { Person } from '../people/usePeople';
import { usePersonRowAction } from '../people/usePersonRowAction';

/** A steward transfers a person to another sheet by id: an entry for the sheet id and a transfer button. The
 *  person, with their grades, terms, contact, aliases and claims, leaves this sheet for the other, so every
 *  figure on the sheet is re-read. Anyone else, a retired person, this sheet's own id, or a name, alias or
 *  contact already on the other sheet is refused with the row's error. */
function PersonTransfer({ sheetId, personId }: { sheetId: string; personId: number }) {
  const queryClient = useQueryClient();
  const [to, setTo] = useState('');

  const transfer = useMutation({
    mutationFn: (toSheetId: string) =>
      postJson<Person>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${personId}/transfer`, { toSheetId }),
    onSuccess: async () => {
      setTo('');
      await queryClient.invalidateQueries({ queryKey: ['sheet', sheetId] });
    },
  });
  const announce = usePersonRowAction(sheetId, personId, transfer.reset);

  return (
    <td>
      <input
        data-testid="person-transfer-to"
        placeholder="Sheet id"
        value={to}
        onChange={(e) => {
          setTo(e.target.value);
          transfer.reset();
        }}
      />{' '}
      <button
        type="button"
        data-testid="person-transfer"
        disabled={transfer.isPending}
        onClick={() => {
          announce();
          transfer.reset();
          transfer.mutate(to);
        }}
      >
        Transfer
      </button>
      {transfer.isError && <span data-testid="person-error">{transfer.error.message}</span>}
    </td>
  );
}

export const contributions = [
  PersonColumnHead.fill({ order: 56, Component: () => <th>Transfer</th> }),
  PersonCells.fill({ order: 56, Component: PersonTransfer }),
];
import { useState } from 'react';
import { useMutation } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { SheetBody } from '../../slots/defs/sheetBody';

/** The audit viewer: the sheet's audit lines exactly as the audit file holds them, newest first. A name
 *  in the filter keeps only the lines about that person (name=<name> or person=<name>, compared ignoring
 *  case and surrounding spaces). It reads the file; it records nothing. */
function AuditViewer({ sheetId }: { sheetId: string }) {
  const [filter, setFilter] = useState('');

  const show = useMutation({
    mutationFn: (name: string) =>
      getJson<{ lines: string[] }>(
        `/api/sheets/${encodeURIComponent(sheetId)}/audit?name=${encodeURIComponent(name)}`,
      ),
  });

  return (
    <section data-testid="audit">
      <h2>Audit</h2>
      <input
        data-testid="audit-filter"
        placeholder="Person name (blank for all)"
        value={filter}
        onChange={(e) => {
          setFilter(e.target.value);
          show.reset();
        }}
      />{' '}
      <button
        type="button"
        data-testid="audit-show"
        disabled={show.isPending}
        onClick={() => {
          show.reset();
          show.mutate(filter);
        }}
      >
        Show
      </button>
      {show.isError && <span data-testid="audit-error">{show.error.message}</span>}
      {show.isSuccess && (
        <ul>
          {show.data.lines.map((line, i) => (
            <li key={i} data-testid="audit-line">
              {line}
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}

export const contribution = SheetBody.fill({
  order: 90,
  Component: ({ sheetId }) => <AuditViewer sheetId={sheetId} />,
});
package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import net.officefloor.hq.app.settings.SettingsRepository;
import org.springframework.beans.factory.ObjectProvider;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    /** The lines that only report figures (or tell of a change already recorded): never marked for a delegator. */
    private static final Set<String> REPORTS = Set.of("ROLLUP", "TOTALS", "SNAPSHOT", "ALERT", "NOTIFY");

    private final Path file;

    private final ObjectProvider<SettingsRepository> settings;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path, ObjectProvider<SettingsRepository> settings) {
        this.file = Path.of(path);
        this.settings = settings;
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. A change made by a user acting
     *  under a delegation of the steward role (one covering the sheet's today) ends with for=<the steward
     *  who delegated>. */
    public synchronized void record(String entry) {
        entry = entry + delegatedFor(entry);
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /** " for=<steward>" when the record (EVENT sheet=<id> by=<user> ...) is a change by a delegated user. */
    private String delegatedFor(String entry) {
        String[] parts = entry.split(" ", 4);
        if (parts.length < 3 || REPORTS.contains(parts[0]) || !parts[1].startsWith("sheet=") || !parts[2].startsWith("by=")) {
            return "";
        }
